import base64
from pathlib import Path
import html

ASSETS = Path(__file__).parent/'assets'/'studio'
EXAMPLES = {
 'Photographer portfolio': {'name':'MIRA LANE', 'title':'A quieter way of seeing.', 'idea':'A portfolio for a photographer who loves bold type and quiet landscapes.', 'audience':'Art directors and local photography clients', 'structure':'Selected work, biography, enquiry section', 'interaction':'Filter the gallery by Landscapes or Architecture', 'options':['All','Landscapes','Architecture'], 'labels':['Coastal light','Studies in stillness'], 'images':['landscape.jpg','architecture.jpg']},
 'Ceramics studio': {'name':'EARTH / FORM', 'title':'Objects for everyday rituals.', 'idea':'A ceramics studio website with warm material colours and a working collection selector.', 'audience':'People exploring handmade homeware', 'structure':'Collection, materials, studio story', 'interaction':'Choose Tableware or Objects to filter the collection', 'options':['All','Tableware','Objects'], 'labels':['The daily collection','Objects, slowly made'], 'images':['ceramics.jpg','ceramics.jpg']},
 'Independent design event': {'name':'OFF / GRID', 'title':'Ideas outside the lines.', 'idea':'An independent design event with assertive typography and a filterable session schedule.', 'audience':'Designers, creative developers and students', 'structure':'Event introduction, schedule, venue details', 'interaction':'Filter the schedule by Talks or Workshops', 'options':['All','Talks','Workshops'], 'labels':['10:00 / Design beyond the grid','14:00 / Build something unexpected'], 'images':[]},
}
STYLES = ['Editorial', 'Bold grid', 'Quiet minimal']

def image_data(name):
    return 'data:image/jpeg;base64,'+base64.b64encode((ASSETS/name).read_bytes()).decode()

def example_html(name, style='Editorial', broken=False):
    item=EXAMPLES[name]
    categories=item['options']
    controls=''.join('<button data-filter="'+html.escape(value)+'" aria-pressed="'+str(i==0).lower()+'">'+html.escape(value)+'</button>' for i,value in enumerate(categories))
    cards=[]
    for i,label in enumerate(item['labels']):
        imagery=('<img src="'+image_data(item['images'][i])+'" alt="'+('Ceramic vessels' if name=='Ceramics studio' else 'Mountain lake landscape' if i==0 else 'Architectural facade')+'">') if item['images'] else '<div class="session-number">0'+str(i+1)+'</div>'
        cards.append('<article data-category="'+html.escape(categories[i+1])+'">'+imagery+'<h2>'+html.escape(label)+'</h2><p>'+html.escape(categories[i+1])+'</p></article>')
    script="""document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{const selected=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));document.querySelectorAll('[data-category]').forEach(card=>card.hidden=selected!=='All'&&card.dataset.category!==selected);document.querySelector('#result').textContent=selected==='All'?'Showing all 2 items':'Showing 1 item · '+selected;}));"""
    if broken:script='// Simulated demonstration: the filter listener is missing.'
    return '''<!doctype html><html lang="en"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'''+html.escape(item['name'])+''' — prebuilt example</title><style>
*{box-sizing:border-box}body{margin:0;padding:24px;background:#eee9df;color:#242824;font:14px/1.6 Arial,sans-serif}nav{display:flex;justify-content:space-between;gap:16px;align-items:center;border-bottom:1px solid #bdbdb1;padding-bottom:14px}a{color:inherit}h1{font:italic 400 clamp(40px,6vw,68px)/1.02 Georgia,serif;max-width:12ch;letter-spacing:-.045em;margin:32px 0 18px}.intro{max-width:40ch;color:#66665e}.filters{display:flex;gap:8px;flex-wrap:wrap;margin:24px 0 10px}button{min-height:44px;border:1px solid #77796d;background:transparent;color:inherit;padding:8px 14px;cursor:pointer}button[aria-pressed="true"]{background:#272f28;color:#fff}button:focus-visible,a:focus-visible{outline:3px solid #ad3515;outline-offset:3px}.gallery{display:grid;grid-template-columns:1.25fr 1fr;gap:16px;margin-top:18px}article[hidden]{display:none}img{width:100%;height:250px;object-fit:cover;display:block}h2{font-size:16px;margin:10px 0 0}article p,#result,footer{font-size:12px}footer{border-top:1px solid #bdbdb1;margin-top:28px;padding-top:16px;color:#65655f}.session-number{font:bold 80px/1 Arial;background:#ff5a24;padding:30px}.bold-grid{background:#1d211f;color:#f4f1e9}.bold-grid h1{font:bold clamp(44px,7vw,78px)/.95 Arial,sans-serif;max-width:15ch;text-transform:uppercase}.bold-grid .intro{color:#c2c5bb}.bold-grid .gallery{grid-template-columns:1fr 1fr;border-top:4px solid #ff5a24;padding-top:20px}.bold-grid button{color:#f4f1e9;border-color:#93988c}.bold-grid button[aria-pressed="true"]{background:#ff5a24;color:#191919}.quiet-minimal{background:#fffdf8;padding:40px}.quiet-minimal h1{font:400 clamp(34px,5vw,52px)/1.15 Arial,sans-serif;max-width:18ch;letter-spacing:-.04em}.quiet-minimal .gallery{grid-template-columns:1fr;gap:28px}.quiet-minimal img{height:280px}.quiet-minimal article{display:grid;grid-template-columns:1.4fr 1fr;gap:18px}.quiet-minimal article[hidden]{display:none}.quiet-minimal article p{grid-column:2}.quiet-minimal button{border-radius:3px}@media(max-width:440px){body,.quiet-minimal{padding:18px}.gallery,.bold-grid .gallery{grid-template-columns:1fr}.quiet-minimal article{display:block}img{height:220px}h1{font-size:44px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto;transition:none!important}}
</style><body class="'''+style.lower().replace(' ','-')+'"><nav><strong>'+html.escape(item['name'])+'''</strong><a href="#collection">Explore ↓</a></nav><h1>'''+html.escape(item['title'])+'</h1><p class="intro">'+html.escape(item['idea'])+'</p><section id="collection"><div class="filters">'+controls+'</div><p id="result" role="status">Showing all 2 items</p><div class="gallery">'+''.join(cards)+'</div></section><footer>Interactive demo · Prebuilt example. Images: Unsplash, stored locally. No purchasing, booking or email service.</footer><script>'+script+'</script></body></html>'
